// Generate 20 buyers for remaining states using real regional companies
function generateStateBuyers(stateCode, stateName, primaryUseCase, companies) {
  return companies.map((c, i) => ({
    display_company: c.name,
    contact_phone: c.phone,
    contact_phone_type: c.phoneType || 'General',
    contact_email: c.email,
    contact_website: c.website,
    budget_min: c.budgetMin || 200000,
    budget_max: c.budgetMax || 10000000,
    min_acreage: c.minAcres || 50,
    max_acreage: c.maxAcres || 5000,
    use_case: c.useCase || primaryUseCase,
    target_state: stateCode,
  }));
}

